<section class="page-header"><div><a class="back-link" href="<?= url('portal/client') ?>"><i class="fa-solid fa-arrow-left"></i> Back to client portal</a><h1><?= e($project['name']) ?></h1><p><?= e($project['project_code']) ?> · Expected <?= e(date('d M Y',strtotime($project['expected_completion_date']))) ?></p></div><span class="status-badge <?= status_class($project['status']) ?>"><?= e($project['status']) ?></span></section><section class="panel project-summary"><div><span>Overall progress</span><strong><?= (int)$project['progress'] ?>%</strong></div><div class="large-progress"><i style="width:<?= (int)$project['progress'] ?>%"></i></div><p><?= nl2br(e($project['client_visible_notes']?:$project['description'])) ?></p></section><div class="portal-grid"><section class="panel"><div class="panel-head"><div><h2>Milestones</h2><p>Delivery checkpoints</p></div></div><div class="timeline-list"><?php foreach($milestones as $item):?><div class="timeline-item"><span class="timeline-dot"></span><div><strong><?= e($item['title']) ?></strong><small><?= e(date('d M Y',strtotime($item['due_date']))) ?> · <?= e($item['status']) ?></small></div></div><?php endforeach;?><?php if(!$milestones):?><div class="empty-inline">No milestones published.</div><?php endif;?></div></section><section class="panel"><div class="panel-head"><div><h2>Project team</h2><p>Assigned team and roles</p></div></div><div class="team-list"><?php foreach($members as $member):?><div><span class="avatar"><?= e(mb_substr($member['name'],0,1)) ?></span><span><strong><?= e($member['name']) ?></strong><small><?= e($member['role_name']) ?></small></span></div><?php endforeach;?></div></section><section class="panel span-2"><div class="panel-head"><div><h2>Project updates</h2><p>Client-visible delivery timeline</p></div></div><div class="timeline-list"><?php foreach($updates as $item):?><div class="timeline-item"><span class="timeline-dot"></span><div><strong><?= e($item['title']) ?></strong><p><?= nl2br(e($item['details'])) ?></p><small><?= e($item['name']) ?> · <?= e(date('d M Y, g:i A',strtotime($item['created_at']))) ?></small></div></div><?php endforeach;?><?php if(!$updates):?><div class="empty-inline">No project updates published yet.</div><?php endif;?></div></section><?php if($files):?><section class="panel span-2"><div class="panel-head"><div><h2>Shared files</h2><p>Documents published by the project team</p></div></div><div class="compact-list"><?php foreach($files as $file):?><a class="list-row" href="<?= url('portal/project-files/'.$file['id']) ?>"><span class="list-icon"><i class="fa-solid fa-file-arrow-down"></i></span><span class="list-main"><strong><?= e($file['title']) ?></strong><small><?= e(date('d M Y',strtotime($file['created_at']))) ?></small></span><i class="fa-solid fa-download"></i></a><?php endforeach;?></div></section><?php endif;?></div>
